    v = e1_a &&& 0x1
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = e1_b &&& 0x3
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 2
    %{a: e2_a, b: e2_b} = e2
    v = e2_a &&& 0x1
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = e2_b &&& 0x3
