    bits_read = bits_read + 8
    e1_b = v
    e1 = %Example.Eleven{a: e1_a, b: e1_b}
    v = rv >>> 11 &&& 0x7
    bits_read = bits_read + 3
    e2_a = v
    v = rv >>> 14 &&& 0xFF
    bits_read = bits_read + 8
    e2_b = v
    e2 = %Example.Eleven{a: e2_a, b: e2_b}
