    e3_b = v
    e3 = %Example.Eleven{a: e3_a, b: e3_b}
    v = rv >>> 33 &&& 0x7
    bits_read = bits_read + 3
    e4_a = v
    v = rv >>> 36
    bits_read = bits_read + 8
    e4_b = v
    e4 = %Example.Eleven{a: e4_a, b: e4_b}
    r_arr_eleven_items(remaining - 4, [e4, e3, e2, e1 | acc], data, num_bits, bits_read)
