  defp w_arr_nested_items([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_arr_nested_items([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    %{a: e1_a, b: e1_b} = e1
    v = e1_a &&& 0x7
